import React from "react";
import { motion } from "framer-motion";

const HomePage = () => {
  return (
    <div className="w-full min-h-screen bg-gradient-to-b from-green-50 to-white font-sans overflow-x-hidden">
      
      {/* Navbar */}
      <nav className="w-full bg-green-50 shadow-md fixed top-0 left-0 z-50">
        <div className="max-w-7xl mx-auto px-8 md:px-20 flex items-center justify-between h-20">
          <div className="text-2xl font-bold text-green-700">
            EcoPack <span className="text-green-600">AI</span>
          </div>
          <ul className="hidden md:flex space-x-8 text-green-700 font-semibold">
            <li className="hover:text-green-900 cursor-pointer transition">Home</li>
            <li className="hover:text-green-900 cursor-pointer transition">About</li>
            <li className="hover:text-green-900 cursor-pointer transition">Login/Signup</li>
          </ul>
          {/* Mobile menu placeholder */}
          <div className="md:hidden">
            {/* You can add a hamburger menu here later */}
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="flex flex-col md:flex-row items-center justify-between px-8 md:px-20 py-28 pt-36 bg-green-50 rounded-b-3xl shadow-xl relative overflow-hidden">
        <motion.div
          className="md:w-1/2 space-y-6 z-10"
          initial={{ opacity: 0, x: -50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 1 }}
        >
          <h1 className="text-4xl md:text-5xl font-bold text-green-900">
            Welcome to <span className="text-green-600">EcoPack AI</span>
          </h1>
          <p className="text-gray-700 text-lg md:text-xl">
            Revolutionizing packaging with AI-driven eco-friendly solutions. Reduce waste, save resources, and make a positive impact on our planet.
          </p>
          <div className="flex space-x-4">
            <button className="bg-green-600 text-white px-6 py-3 rounded-lg shadow-lg transform hover:scale-105 hover:bg-green-700 transition duration-300">
              Get Started
            </button>
            <button className="bg-white text-green-600 border-2 border-green-600 px-6 py-3 rounded-lg shadow-lg transform hover:scale-105 hover:bg-green-50 transition duration-300">
              Learn More
            </button>
          </div>
        </motion.div>

        <motion.div
          className="md:w-1/2 mt-10 md:mt-0 z-10"
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 1 }}
        >
          <img
            src="./images/ecoLogo.png"
            alt="Eco Packaging"
            className="rounded-3xl shadow-2xl hover:scale-105 transform transition duration-500"
          />
        </motion.div>

        {/* Background Shapes */}
        <div className="absolute top-0 left-0 w-64 h-64 bg-green-200 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse"></div>
        <div className="absolute bottom-0 right-0 w-72 h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-pulse"></div>
      </section>

      {/* Features Section */}
      <section className="px-8 md:px-20 py-20 grid grid-cols-1 md:grid-cols-3 gap-10 text-center">
        {[
          {
            title: "AI-Powered Analysis",
            description: "Smart recommendations for sustainable packaging based on AI insights.",
          },
          {
            title: "Eco-Friendly Materials",
            description: "Discover biodegradable, recyclable, and reusable packaging options.",
          },
          {
            title: "Track & Reduce Waste",
            description: "Monitor packaging impact and optimize for minimal environmental footprint.",
          },
        ].map((feature, idx) => (
          <motion.div
            key={idx}
            className="bg-white p-8 rounded-3xl shadow-xl hover:shadow-2xl transform hover:scale-105 transition duration-500"
            initial={{ opacity: 0, y: 50 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: idx * 0.2 }}
          >
            <h2 className="text-2xl font-semibold text-green-700 mb-4">{feature.title}</h2>
            <p className="text-gray-600">{feature.description}</p>
          </motion.div>
        ))}
      </section>

      {/* How It Works Section */}
      <section className="bg-green-50 py-24 px-8 md:px-20 text-center">
        <h2 className="text-3xl md:text-4xl font-bold text-green-800 mb-12">
          How EcoPack AI Works
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
          {[
            {
              step: "01",
              title: "Upload Product Info",
              description: "Provide details about your product and packaging requirements.",
            },
            {
              step: "02",
              title: "AI Suggests Packaging",
              description: "Our AI analyzes and recommends the most eco-friendly packaging solutions.",
            },
            {
              step: "03",
              title: "Track Impact",
              description: "Monitor environmental impact and optimize packaging continuously.",
            },
          ].map((step, idx) => (
            <motion.div
              key={idx}
              className="bg-white p-8 rounded-3xl shadow-lg hover:shadow-2xl transform hover:scale-105 transition duration-500"
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.8, delay: idx * 0.2 }}
            >
              <div className="text-green-600 text-4xl font-bold mb-4">{step.step}</div>
              <h3 className="text-2xl font-semibold mb-2">{step.title}</h3>
              <p className="text-gray-600">{step.description}</p>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Call to Action */}
      <motion.section
        className="bg-green-600 text-white py-28 text-center rounded-t-3xl relative overflow-hidden"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 1 }}
      >
        <h2 className="text-3xl md:text-4xl font-bold mb-6">
          Ready to Make a Difference?
        </h2>
        <p className="text-lg md:text-xl mb-8">
          Join us in creating smarter, sustainable packaging solutions.
        </p>
        <button className="bg-white text-green-600 px-10 py-4 rounded-lg font-semibold shadow-lg transform hover:scale-105 hover:bg-green-50 transition duration-300">
          Try EcoPack AI Now
        </button>

        <div className="absolute top-0 left-10 w-32 h-32 bg-green-200 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse"></div>
        <div className="absolute bottom-10 right-10 w-40 h-40 bg-green-300 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-pulse"></div>
      </motion.section>

      {/* Testimonials Section */}
      <section className="px-8 md:px-20 py-24 text-center bg-green-50">
        <h2 className="text-3xl md:text-4xl font-bold text-green-800 mb-12">What Our Users Say</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
          {[
            {
              name: "Sarah J.",
              feedback: "EcoPack AI transformed our packaging process! We reduced waste by 40%.",
            },
            {
              name: "Michael P.",
              feedback: "Intelligent AI suggestions saved us time and money while staying eco-friendly.",
            },
            {
              name: "Aisha K.",
              feedback: "I love how easy it is to track our environmental impact with EcoPack AI.",
            },
          ].map((user, idx) => (
            <motion.div
              key={idx}
              className="bg-white p-8 rounded-3xl shadow-lg hover:shadow-2xl transform hover:scale-105 transition duration-500"
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.8, delay: idx * 0.2 }}
            >
              <p className="text-gray-600 italic mb-4">"{user.feedback}"</p>
              <h3 className="text-green-700 font-semibold">{user.name}</h3>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-green-800 text-white py-12 px-8 md:px-20 text-center">
        <p>© 2025 EcoPack AI. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default HomePage;
